<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref} from 'vue';import {getLearning,putLearning} from './learning-store';import {gradeQuick,type QuickQuestion,type QuickRecord} from './starship-quiz';import {sections,type Station} from './starship-model';
const props=defineProps<{station:string}>();const emit=defineEmits<{activity:[section:string,mode:string]}>();
const questions=ref<QuickQuestion[]>([]),index=ref(0),answer=ref<number[]>([]),record=ref<QuickRecord>({version:1,hintUsed:false}),checked=ref(false),error=ref(''),busy=ref(false);let disposed=false,serial=0;
const current=computed(()=>questions.value[index.value]);
async function load(){const own=++serial;checked.value=false;answer.value=[];const q=current.value;if(!q)return;try{const saved=await getLearning<QuickRecord>('chapter12:quiz:'+q.id,{version:1,hintUsed:false});if(disposed||own!==serial)return;record.value=saved;if(saved.latest){answer.value=[...saved.latest.answer];checked.value=true;}}catch{error.value='读取测验记录失败，请重试。';}if(q.kind==='order'&&!answer.value.length)answer.value=q.options.map((_,i)=>i).reverse();}
async function save(){busy.value=true;try{await putLearning('chapter12:quiz:'+current.value.id,record.value);error.value='';}catch{error.value='保存失败，当前答案仍保留。';}finally{busy.value=false;}}
function pick(i:number){if(checked.value)return;answer.value=current.value.kind==='multiple'?(answer.value.includes(i)?answer.value.filter(x=>x!==i):[...answer.value,i]):[i];}
async function submit(){if(!answer.value.length)return;const attempt={answer:[...answer.value],passed:gradeQuick(current.value,answer.value),at:new Date().toISOString()};record.value={...record.value,first:record.value.first||attempt,latest:attempt,completedAt:attempt.passed?(record.value.completedAt||attempt.at):record.value.completedAt};checked.value=true;await save();}
function reorder(i:number,d:number){const next=[...answer.value];[next[i],next[i+d]]=[next[i+d],next[i]];answer.value=next;}
function back(){const station=(props.station==='summary'?current.value.id.slice(8):props.station) as Station;emit('activity','chapter_divide_and_conquer/'+sections[station],'lab-'+station);}
onMounted(async()=>{try{const response=await fetch('/chapter12/quizzes.json');if(!response.ok)throw Error();questions.value=(await response.json()).filter((q:QuickQuestion)=>q.station===props.station);if(!disposed)await load();}catch{error.value='测验资源加载失败，请重新打开。';}});onBeforeUnmount(()=>{disposed=true;serial++;});
</script>
<template><section class="starship-workbench"><h3>{{station==='summary'?'舰长综合自检':'即时反馈 · 任务检查'}}</h3><p>先作答，再看解释。允许重试，不限制继续阅读。</p><p v-if="error" role="alert">{{error}} <button v-if="current" @click="save">重试保存</button></p><template v-if="current"><small>{{index+1}} / {{questions.length}} · {{current.kind==='multiple'?'多选题':current.kind==='order'?'步骤排序':'单选题'}}</small><h4>{{current.prompt}}</h4><div v-if="current.kind==='order'" class="starship-order"><div v-for="(value,i) in answer" :key="value"><span>{{current.options[value]}}</span><button :disabled="checked||i===0" :aria-label="'上移 '+current.options[value]" @click="reorder(i,-1)">↑</button><button :disabled="checked||i===answer.length-1" :aria-label="'下移 '+current.options[value]" @click="reorder(i,1)">↓</button></div></div><div v-else class="starship-options"><button v-for="(option,i) in current.options" :key="i" :aria-pressed="answer.includes(i)" :disabled="checked" @click="pick(i)">{{option}}</button></div><button :disabled="checked||busy||!answer.length" @click="submit">提交答案</button><button :disabled="busy" @click="record.hintUsed=true;save()">思路提示</button><p v-if="record.hintUsed">{{current.hint}}</p><div v-if="checked" role="status"><strong>{{record.latest?.passed?'判断正确':'暂未答对，可以重试'}}</strong><ul><li v-for="i in answer" :key="i">{{current.feedback[i]}}</li><li v-if="current.kind==='multiple'&&!record.latest?.passed">检查是否存在漏选或多选。</li><li v-if="current.kind==='order'&&!record.latest?.passed">检查递归停止、拆分与返回的先后关系。</li></ul><button @click="checked=false">重新作答</button><button @click="back">回到对应实验</button></div><div class="execution-actions"><button :disabled="index===0||busy" @click="index--;load()">上一题</button><button :disabled="index===questions.length-1||busy" @click="index++;load()">{{checked?'下一题':'跳过此题'}}</button></div></template></section></template>
